WITH cs AS MATERIALIZED (SELECT lower(tt.g[1]) AS relname, kk.k AS attname, 's' AS route FROM pg_trigger tg, lower(pg_get_functiondef(tg.tgfoid)) td(d), LATERAL (SELECT kd.g[1] AS k FROM regexp_matches(td.d, '(?:new[.])?raw_user_meta_data(?:[)]|::jsonb?|[[:space:]])*(?:->>?|#>>?|[[])[[:space:]]*''[{]?((?:[^]''}]|'''')+)', 'g') kd(g) UNION SELECT kv.g[1] FROM regexp_matches(td.d, '[[:<:]]([a-z_][a-z0-9_]*)[[:>:]][[:space:]]*(?:jsonb?)?[[:space:]]*(?::=|=|[[:<:]]default[[:>:]])[[:space:]]*(?:[(][[:space:]]*|coalesce[[:space:]]*[(][[:space:]]*)*(?:new[.])?raw_user_meta_data|[[:<:]]select[[:space:]]+(?:[(][[:space:]]*)*(?:new[.])?raw_user_meta_data(?:[[:space:]]*[)]|[[:space:]]*::jsonb?)*[[:space:]]+into[[:space:]]+(?:strict[[:space:]]+)?([a-z_][a-z0-9_]*)', 'g') va(g), regexp_matches(td.d, '[[:<:]]' || coalesce(va.g[1], va.g[2]) || '[[:>:]](?:[)]|::jsonb?|[[:space:]])*(?:->>?|#>>?|[[])[[:space:]]*''[{]?((?:[^]''}]|'''')+)', 'g') kv(g)) kk, regexp_matches(td.d, '[[:<:]](?:insert[[:space:]]+into|merge[[:space:]]+into|update)[[:space:]]+(?:only[[:space:]]+)?(?:[a-z0-9_[.dollar-sign.]"]+[.])?"?([a-z0-9_[.dollar-sign.]]+)', 'g') tt(g) WHERE tg.tgrelid::regclass::text = 'auth.users' AND NOT tg.tgisinternal AND lower(tt.g[1]) NOT IN ('set', 'only', 'strict') UNION ALL SELECT lower(c.relname), lower(a.attname), CASE WHEN NOT c.relrowsecurity OR bool_or(o.own AND NOT a.attname = ANY (o.w)) THEN 'u' ELSE 'm' END FROM pg_class c JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped AND NOT EXISTS (SELECT 1 FROM pg_index ui WHERE ui.indrelid = c.oid AND ui.indisunique AND ui.indnatts = 1 AND ui.indkey[0] = a.attnum AND ui.indpred IS NULL) JOIN pg_roles g ON (g.rolname IN ('anon', 'authenticated') OR g.rolname NOT IN ('service_role', 'authenticator') AND pg_has_role((SELECT rr.oid FROM pg_roles rr WHERE rr.rolname = 'authenticator'), g.oid, 'MEMBER')) AND has_column_privilege(g.oid, c.oid, a.attnum, 'UPDATE') LEFT JOIN (SELECT polrelid, polroles, regexp_replace(pg_get_expr(polqual, polrelid), '[[:<:]](?!(?:coalesce|nullif|greatest|least)[(])[[:alnum:]_]+[(][[:space:]]*(?:auth[.]uid[(][)]|[(][[:space:]]*select[[:space:]]+auth[.]uid[(][)](?:[[:space:]]+as[[:space:]]+uid)?[[:space:]]*[)])(?=(?:[[:space:]]*,[[:space:]]*''(?:[^'']|'''')*''(?:::[[:alnum:]_ .]+)?)*[[:space:]]*[)])', '', 'gi') ~* 'auth[.]uid[(]|[.'']sub''|^[(]?true[[:>:]]' AS own, regexp_split_to_array(x, '[^[:alnum:]_[.dollar-sign.]]+') AS w, ARRAY(SELECT coalesce(m[1], m[2]) FROM regexp_matches(x, '([[:alnum:]_]+) (?:=|IN) (?:''|[(] select|auth[.]uid)|(?:uid[(]?[)]|''(?:::[[:alnum:]_ ]+)?) = ([[:alnum:]_]+)', 'gi') m WHERE x !~ '(<>|!=|!~|[[:<:]]NOT[[:>:]](?![[:space:]]+NULL)|[[:<:]]OR[[:>:]]|[[:<:]]CASE[[:>:]]|[[:<:]]DISTINCT[[:>:]])') AS k FROM pg_policy, coalesce(pg_get_expr(polwithcheck, polrelid), pg_get_expr(polqual, polrelid)) x WHERE polcmd IN ('w', '*') AND polpermissive) o ON o.polrelid = c.oid AND EXISTS (SELECT 1 FROM unnest(o.polroles) r WHERE r = 0 OR pg_has_role(g.oid, r, 'USAGE')) WHERE c.relkind IN ('r', 'p') GROUP BY 1, 2, c.relrowsecurity HAVING NOT c.relrowsecurity OR bool_or(NOT a.attname = ANY (o.k))), cf AS MATERIALIZED (SELECT hd.objid AS pol, string_agg(pg_get_functiondef(hp.oid), ' ') AS h FROM pg_depend hd JOIN pg_proc hp ON hp.oid = hd.refobjid JOIN pg_namespace hn ON hn.oid = hp.pronamespace WHERE hd.classid = 3256 AND hp.prokind <> 'a' AND hn.oid <> 11 AND (hn.nspname, hp.proname) NOT IN (('auth', 'uid'), ('auth', 'jwt'), ('auth', 'role'), ('auth', 'email')) GROUP BY 1), cv AS MATERIALIZED (SELECT pol, array_agg(DISTINCT route) AS r FROM (SELECT pol, route FROM (SELECT cd.objid AS pol, lower(cc.relname) AS rn, lower(ca.attname) AS an FROM pg_depend cd JOIN pg_attribute ca ON ca.attrelid = cd.refobjid AND ca.attnum = cd.refobjsubid JOIN pg_class cc ON cc.oid = cd.refobjid WHERE cd.classid = 3256 OFFSET 0) d JOIN cs ON relname = rn AND attname = an UNION ALL SELECT pol, route FROM (SELECT pol, u, w FROM cf, regexp_split_to_array(lower(h), '[^[:alnum:]_[.dollar-sign.]]+') w, unnest(w) u OFFSET 0) hw JOIN cs ON relname = u AND attname = ANY (w)) x GROUP BY 1)
SELECT n.nspname::text AS schema_name, c.relname::text AS table_name, p.polname::text AS policy_name,
       CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update' WHEN 'd' THEN 'delete'
         WHEN '*' THEN 'all' END AS command,
       p.polpermissive AS permissive,
       ((p.polcmd IN ('r', '*', 'w', 'd') AND btrim(coalesce(pg_get_expr(p.polqual, p.polrelid), '')) IN ('true', '(true)'))
        OR (p.polcmd IN ('a', 'w', '*') AND btrim(coalesce(pg_get_expr(p.polwithcheck, p.polrelid), pg_get_expr(p.polqual, p.polrelid), '')) IN ('true', '(true)'))) AS always_true,
       ((coalesce(pg_get_expr(p.polqual, p.polrelid), '') || ' ' || coalesce(pg_get_expr(p.polwithcheck, p.polrelid), '')
         || ' ' || coalesce(hx.h, '')) ~* '(user_metadata|raw_user_meta_data)' OR coalesce(t.r && '{s}', false)) AS reads_user_metadata,
       coalesce(t.r, '{}') AS trusted_routes,
       (coalesce(pg_get_expr(p.polqual, p.polrelid), '') || ' ' || coalesce(pg_get_expr(p.polwithcheck, p.polrelid),
        '')) ~ 'auth[.]uid[(][)]' AS owner_match,
       ARRAY(SELECT CASE WHEN pr.r = 0 THEN 'public' ELSE g.rolname::text END
               FROM unnest(p.polroles) WITH ORDINALITY AS pr(r, i) LEFT JOIN pg_roles g ON g.oid = pr.r
              ORDER BY pr.i) AS roles,
       pg_get_expr(p.polqual, p.polrelid) AS using_expression,
       pg_get_expr(p.polwithcheck, p.polrelid) AS check_expression
  FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  LEFT JOIN cf hx ON hx.pol = p.oid LEFT JOIN cv t ON t.pol = p.oid
 WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast', 'auth', 'storage', 'extensions', 'graphql', 'graphql_public', 'realtime', '_realtime', 'vault', 'pgsodium', 'pgsodium_masks', 'supabase_functions', 'supabase_migrations', 'net', 'cron', 'pgbouncer', '_analytics', 'pgmq') AND n.nspname !~ '^pg_'
 ORDER BY 1, 2, 3
